import type { ReactiveController, ReactiveControllerHost } from 'lit';

export interface FilterOptions {
  /** CSS selector for filterable items. */
  selector?: string;
  /** Filter mode. Default: 'includes' */
  mode?: 'includes' | 'startsWith' | ((itemText: string, query: string) => boolean);
  /** How to get text from items. Default: 'textContent' */
  textSelector?: 'textContent' | 'aria-label';
}

/**
 * Shared filtering logic for Combobox and Command Palette.
 * Toggles `hidden` on items based on a query string.
 */
export class FilterController implements ReactiveController {
  private _host: ReactiveControllerHost & HTMLElement;
  private _options: Required<FilterOptions>;
  private _query = '';

  constructor(host: ReactiveControllerHost & HTMLElement, options?: FilterOptions) {
    this._host = host;
    this._options = {
      selector: options?.selector ?? '[role="option"]',
      mode: options?.mode ?? 'includes',
      textSelector: options?.textSelector ?? 'textContent',
    };
    host.addController(this);
  }

  hostConnected(): void {}
  hostDisconnected(): void {}

  /** Current filter query. */
  get query(): string {
    return this._query;
  }

  /** Update the filter query and toggle item visibility. Returns the number of visible items. */
  filter(query: string): number {
    this._query = query;
    const items = this._getItems();
    const normalizedQuery = query.toLowerCase().trim();
    let visibleCount = 0;

    for (const item of items) {
      const text = this._getItemText(item);
      const matches = normalizedQuery === '' || this._matches(text, normalizedQuery);
      item.hidden = !matches;
      if (matches) visibleCount++;
    }

    return visibleCount;
  }

  /** Reset filter — show all items. */
  reset(): void {
    this._query = '';
    for (const item of this._getItems()) {
      item.hidden = false;
    }
  }

  /** Update the filter mode. */
  setMode(mode: FilterOptions['mode']): void {
    if (mode) this._options.mode = mode;
  }

  private _getItems(): HTMLElement[] {
    return Array.from(this._host.querySelectorAll<HTMLElement>(this._options.selector));
  }

  private _getItemText(item: HTMLElement): string {
    if (this._options.textSelector === 'aria-label') {
      return (item.getAttribute('aria-label') ?? item.textContent ?? '').trim().toLowerCase();
    }
    return (item.textContent ?? '').trim().toLowerCase();
  }

  private _matches(text: string, query: string): boolean {
    if (typeof this._options.mode === 'function') {
      return this._options.mode(text, query);
    }
    if (this._options.mode === 'startsWith') {
      return text.startsWith(query);
    }
    return text.includes(query);
  }
}

import type { ReactiveController, ReactiveControllerHost } from 'lit';

export interface ClickOutsideOptions {
  /** Called when a click occurs outside the host element. */
  onClickOutside: () => void;
  /** Enable/disable the listener. Default: true */
  active?: boolean;
}

/**
 * Detects clicks outside an element. Used by Popover, Dropdown, etc.
 */
export class ClickOutsideController implements ReactiveController {
  private _host: ReactiveControllerHost & HTMLElement;
  private _options: Required<ClickOutsideOptions>;
  private _handlePointerDown = this._onPointerDown.bind(this);

  active: boolean;

  constructor(host: ReactiveControllerHost & HTMLElement, options: ClickOutsideOptions) {
    this._host = host;
    this._options = {
      onClickOutside: options.onClickOutside,
      active: options.active ?? true,
    };
    this.active = this._options.active;
    host.addController(this);
  }

  hostConnected(): void {
    if (this.active) this._addListener();
  }

  hostDisconnected(): void {
    this._removeListener();
  }

  hostUpdated(): void {
    if (this.active) {
      this._addListener();
    } else {
      this._removeListener();
    }
  }

  private _addListener(): void {
    document.addEventListener('pointerdown', this._handlePointerDown, true);
  }

  private _removeListener(): void {
    document.removeEventListener('pointerdown', this._handlePointerDown, true);
  }

  private _onPointerDown(event: PointerEvent): void {
    if (!this.active) return;
    const path = event.composedPath();
    if (!path.includes(this._host)) {
      this._options.onClickOutside();
    }
  }
}

import type { ReactiveController, ReactiveControllerHost } from 'lit';

export interface FocusTrapOptions {
  /** Enable/disable the trap reactively. */
  active?: boolean;
  /** Return focus to the previously-focused element on deactivation. Default: true */
  returnFocusOnDeactivate?: boolean;
  /** CSS selector for the element that should receive initial focus. */
  initialFocus?: string;
}

const FOCUSABLE =
  'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

/**
 * Contains tab focus within a host element. Used by Dialog, Popover, etc.
 */
export class FocusTrapController implements ReactiveController {
  private _host: ReactiveControllerHost & HTMLElement;
  private _options: Required<FocusTrapOptions>;
  private _previousFocus: HTMLElement | null = null;
  private _handleKeyDown = this._onKeyDown.bind(this);

  active: boolean;

  constructor(host: ReactiveControllerHost & HTMLElement, options?: FocusTrapOptions) {
    this._host = host;
    this._options = {
      active: options?.active ?? false,
      returnFocusOnDeactivate: options?.returnFocusOnDeactivate ?? true,
      initialFocus: options?.initialFocus ?? '',
    };
    this.active = this._options.active;
    host.addController(this);
  }

  hostConnected(): void {
    if (this.active) this._activate();
  }

  hostDisconnected(): void {
    this._deactivate();
  }

  hostUpdated(): void {
    if (this.active) {
      this._activate();
    } else {
      this._deactivate();
    }
  }

  private _activate(): void {
    this._previousFocus ??= document.activeElement as HTMLElement | null;
    this._host.addEventListener('keydown', this._handleKeyDown);

    // Move focus into the trap on next frame
    requestAnimationFrame(() => {
      if (!this.active) return;
      const initial = this._options.initialFocus
        ? this._host.shadowRoot?.querySelector<HTMLElement>(this._options.initialFocus) ??
          this._host.querySelector<HTMLElement>(this._options.initialFocus)
        : null;
      if (initial) {
        initial.focus();
      } else {
        this._getFocusableElements()[0]?.focus();
      }
    });
  }

  private _deactivate(): void {
    this._host.removeEventListener('keydown', this._handleKeyDown);
    if (this._options.returnFocusOnDeactivate && this._previousFocus) {
      this._previousFocus.focus();
      this._previousFocus = null;
    }
  }

  private _onKeyDown(event: Event): void {
    const e = event as KeyboardEvent;
    if (e.key !== 'Tab') return;

    const focusable = this._getFocusableElements();
    if (focusable.length === 0) {
      e.preventDefault();
      return;
    }

    const first = focusable[0]!;
    const last = focusable[focusable.length - 1]!;

    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }

  private _getFocusableElements(): HTMLElement[] {
    const root = this._host.shadowRoot ?? this._host;
    const slotted = this._host.querySelectorAll<HTMLElement>(FOCUSABLE);
    const shadow = root.querySelectorAll<HTMLElement>(FOCUSABLE);
    return [...Array.from(shadow), ...Array.from(slotted)].filter(
      (el) => !el.hasAttribute('disabled') && el.offsetParent !== null,
    );
  }
}

import type { ReactiveController, ReactiveControllerHost } from 'lit';

export interface CalendarOptions {
  /** Locale for Intl.DateTimeFormat. Default: undefined (browser default) */
  locale?: string;
  /** Minimum selectable date (ISO string YYYY-MM-DD). */
  min?: string;
  /** Maximum selectable date (ISO string YYYY-MM-DD). */
  max?: string;
}

export interface CalendarDay {
  /** ISO date string YYYY-MM-DD */
  date: string;
  /** Day of month (1-31) */
  day: number;
  /** Whether this day belongs to the currently displayed month */
  currentMonth: boolean;
  /** Whether this day is today */
  today: boolean;
  /** Whether this day is outside the min/max range */
  disabled: boolean;
}

/**
 * Pure logic for calendar math — no DOM.
 * Generates a 6×7 day grid for any month, handles month/year navigation,
 * date comparison, and min/max constraints.
 * Uses native Intl.DateTimeFormat for locale-aware names.
 */
export class CalendarController implements ReactiveController {
  private _host: ReactiveControllerHost;
  private _locale: string | undefined;
  private _min: string;
  private _max: string;
  private _year: number;
  private _month: number; // 0-indexed

  constructor(host: ReactiveControllerHost, options?: CalendarOptions) {
    this._host = host;
    this._locale = options?.locale;
    this._min = options?.min ?? '';
    this._max = options?.max ?? '';
    const now = new Date();
    this._year = now.getFullYear();
    this._month = now.getMonth();
    host.addController(this);
  }

  hostConnected(): void {}
  hostDisconnected(): void {}

  /** Current displayed year. */
  get year(): number {
    return this._year;
  }

  /** Current displayed month (0-indexed). */
  get month(): number {
    return this._month;
  }

  /** Formatted month name (e.g. "January"). */
  get monthName(): string {
    const fmt = new Intl.DateTimeFormat(this._locale, { month: 'long' });
    return fmt.format(new Date(this._year, this._month, 1));
  }

  /** Locale-aware weekday short names starting from locale's first day of week. */
  get weekdays(): string[] {
    const fmt = new Intl.DateTimeFormat(this._locale, { weekday: 'short' });
    // Generate weekday names starting from Sunday (0)
    return Array.from({ length: 7 }, (_, i) => {
      // Jan 4, 2024 is a Thursday; use a known Sunday: Jan 7, 2024
      const d = new Date(2024, 0, 7 + i); // 7 = Sunday
      return fmt.format(d);
    });
  }

  /** Navigate to a specific month/year. */
  setMonth(year: number, month: number): void {
    // Normalize month overflow
    const d = new Date(year, month, 1);
    this._year = d.getFullYear();
    this._month = d.getMonth();
    this._host.requestUpdate();
  }

  /** Go to next month. */
  nextMonth(): void {
    this.setMonth(this._year, this._month + 1);
  }

  /** Go to previous month. */
  prevMonth(): void {
    this.setMonth(this._year, this._month - 1);
  }

  /** Go to next year. */
  nextYear(): void {
    this.setMonth(this._year + 1, this._month);
  }

  /** Go to previous year. */
  prevYear(): void {
    this.setMonth(this._year - 1, this._month);
  }

  /** Navigate to the month containing the given ISO date. */
  goToDate(isoDate: string): void {
    const d = parseISO(isoDate);
    if (d) this.setMonth(d.getFullYear(), d.getMonth());
  }

  /** Update min constraint. */
  setMin(min: string): void {
    this._min = min;
  }

  /** Update max constraint. */
  setMax(max: string): void {
    this._max = max;
  }

  /** Generate the 6×7 grid of CalendarDay objects for the current month. */
  getDays(): CalendarDay[][] {
    const firstOfMonth = new Date(this._year, this._month, 1);
    const startDay = firstOfMonth.getDay(); // 0=Sunday
    const daysInMonth = new Date(this._year, this._month + 1, 0).getDate();

    // Start grid from the Sunday before (or on) the 1st
    const gridStart = new Date(this._year, this._month, 1 - startDay);

    const today = toISO(new Date());
    const grid: CalendarDay[][] = [];

    for (let week = 0; week < 6; week++) {
      const row: CalendarDay[] = [];
      for (let dow = 0; dow < 7; dow++) {
        const d = new Date(gridStart);
        d.setDate(gridStart.getDate() + week * 7 + dow);
        const iso = toISO(d);
        const dayOfMonth = d.getDate();
        const isCurrentMonth = d.getMonth() === this._month && d.getFullYear() === this._year;

        row.push({
          date: iso,
          day: dayOfMonth,
          currentMonth: isCurrentMonth,
          today: iso === today,
          disabled: this._isDisabled(iso),
        });
      }
      grid.push(row);
    }

    return grid;
  }

  /** Check if two ISO date strings represent the same date. */
  isSameDate(a: string, b: string): boolean {
    return a === b;
  }

  private _isDisabled(iso: string): boolean {
    if (this._min && iso < this._min) return true;
    if (this._max && iso > this._max) return true;
    return false;
  }
}

/** Parse an ISO YYYY-MM-DD string to a Date (local time). Returns null if invalid. */
function parseISO(iso: string): Date | null {
  if (!iso || !/^\d{4}-\d{2}-\d{2}$/.test(iso)) return null;
  const [y, m, d] = iso.split('-').map(Number) as [number, number, number];
  return new Date(y, m - 1, d);
}

/** Format a Date as YYYY-MM-DD. */
function toISO(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

import type { ReactiveController, ReactiveControllerHost } from 'lit';

export type AnimationState = 'idle' | 'entering' | 'entered' | 'exiting';

export interface AnimationOptions {
  /** Duration for enter transition in ms. Default: 200 */
  enterDuration?: number;
  /** Duration for exit transition in ms. Default: 150 */
  exitDuration?: number;
}

/**
 * Manages enter/exit animations via `data-state` attribute.
 * Components style transitions using CSS selectors:
 *   [data-state="entering"] / [data-state="entered"] / [data-state="exiting"]
 */
export class AnimationController implements ReactiveController {
  private _host: ReactiveControllerHost & HTMLElement;
  private _options: Required<AnimationOptions>;

  state: AnimationState = 'idle';

  constructor(host: ReactiveControllerHost & HTMLElement, options?: AnimationOptions) {
    this._host = host;
    this._options = {
      enterDuration: options?.enterDuration ?? 200,
      exitDuration: options?.exitDuration ?? 150,
    };
    host.addController(this);
  }

  hostConnected(): void {}
  hostDisconnected(): void {
    this.state = 'idle';
  }

  /** Runs the enter animation on the target element (defaults to host). */
  async enter(el?: HTMLElement): Promise<void> {
    const target = el ?? this._host;
    this.state = 'entering';
    target.setAttribute('data-state', 'entering');

    // Wait one frame for the browser to apply the entering styles
    await new Promise<void>((resolve) => requestAnimationFrame(() => resolve()));

    // Wait for CSS transition to complete, or fall back to duration timeout
    await this._waitForTransition(target, this._options.enterDuration);

    this.state = 'entered';
    target.setAttribute('data-state', 'entered');
  }

  /** Runs the exit animation on the target element (defaults to host). */
  async exit(el?: HTMLElement): Promise<void> {
    const target = el ?? this._host;
    this.state = 'exiting';
    target.setAttribute('data-state', 'exiting');

    await this._waitForTransition(target, this._options.exitDuration);

    this.state = 'idle';
    target.removeAttribute('data-state');
  }

  private _waitForTransition(el: HTMLElement, fallbackMs: number): Promise<void> {
    return new Promise<void>((resolve) => {
      let settled = false;
      const done = () => {
        if (settled) return;
        settled = true;
        el.removeEventListener('transitionend', onEnd);
        resolve();
      };
      const onEnd = (e: TransitionEvent) => {
        if (e.target === el) done();
      };
      el.addEventListener('transitionend', onEnd);
      // Fallback timer in case no CSS transition is defined
      setTimeout(done, fallbackMs + 50);
    });
  }
}

import type { ReactiveController, ReactiveControllerHost } from 'lit';

export interface TypeaheadOptions {
  /** CSS selector for searchable items. */
  selector?: string;
  /** How to get text from items. Default: 'textContent' */
  textSelector?: 'textContent' | 'aria-label';
  /** Reset buffer timeout in ms. Default: 500 */
  timeout?: number;
  /** Called when a match is found. */
  onMatch?: (item: HTMLElement, index: number) => void;
}

/**
 * Type-to-search within a list/menu. Attaches to any composite widget.
 */
export class TypeaheadController implements ReactiveController {
  private _host: ReactiveControllerHost & HTMLElement;
  private _options: Required<TypeaheadOptions>;
  private _buffer = '';
  private _timer: ReturnType<typeof setTimeout> | null = null;
  private _handleKeyDown = this._onKeyDown.bind(this);

  constructor(host: ReactiveControllerHost & HTMLElement, options?: TypeaheadOptions) {
    this._host = host;
    this._options = {
      selector: options?.selector ?? '[role]',
      textSelector: options?.textSelector ?? 'textContent',
      timeout: options?.timeout ?? 500,
      onMatch: options?.onMatch ?? (() => {}),
    };
    host.addController(this);
  }

  hostConnected(): void {
    this._host.addEventListener('keydown', this._handleKeyDown);
  }

  hostDisconnected(): void {
    this._host.removeEventListener('keydown', this._handleKeyDown);
    this._clearTimer();
  }

  private _clearTimer(): void {
    if (this._timer !== null) {
      clearTimeout(this._timer);
      this._timer = null;
    }
  }

  private _getItems(): HTMLElement[] {
    return Array.from(this._host.querySelectorAll<HTMLElement>(this._options.selector)).filter(
      (el) => !el.hasAttribute('disabled') && el.getAttribute('aria-disabled') !== 'true',
    );
  }

  private _getItemText(item: HTMLElement): string {
    if (this._options.textSelector === 'aria-label') {
      return (item.getAttribute('aria-label') ?? item.textContent ?? '').trim().toLowerCase();
    }
    return (item.textContent ?? '').trim().toLowerCase();
  }

  private _onKeyDown(event: Event): void {
    const e = event as KeyboardEvent;

    // Only match printable single characters
    if (e.key.length !== 1 || e.ctrlKey || e.metaKey || e.altKey) return;

    e.preventDefault();
    this._buffer += e.key.toLowerCase();
    this._clearTimer();
    this._timer = setTimeout(() => {
      this._buffer = '';
    }, this._options.timeout);

    const items = this._getItems();
    const match = items.findIndex((item) =>
      this._getItemText(item).startsWith(this._buffer),
    );

    if (match !== -1) {
      this._options.onMatch(items[match]!, match);
    }
  }
}

import type { ReactiveController, ReactiveControllerHost } from 'lit';

export interface RovingTabindexOptions {
  /** Arrow key orientation. Default: 'vertical' */
  orientation?: 'horizontal' | 'vertical' | 'both';
  /** Wrap around at ends. Default: true */
  loop?: boolean;
  /** CSS selector for focusable items. Default: '[role]' */
  selector?: string;
}

/**
 * Arrow key navigation within widget groups. Manages `tabindex` across children.
 * Follows the WAI-ARIA Composite pattern.
 */
export class RovingTabindexController implements ReactiveController {
  private _host: ReactiveControllerHost & HTMLElement;
  private _options: Required<RovingTabindexOptions>;
  private _handleKeyDown = this._onKeyDown.bind(this);
  private _currentIndex = 0;

  constructor(host: ReactiveControllerHost & HTMLElement, options?: RovingTabindexOptions) {
    this._host = host;
    this._options = {
      orientation: options?.orientation ?? 'vertical',
      loop: options?.loop ?? true,
      selector: options?.selector ?? '[role]',
    };
    host.addController(this);
  }

  hostConnected(): void {
    this._host.addEventListener('keydown', this._handleKeyDown);
    this._host.addEventListener('focusin', this._onFocusIn.bind(this));
    requestAnimationFrame(() => this._initTabindex());
  }

  hostDisconnected(): void {
    this._host.removeEventListener('keydown', this._handleKeyDown);
  }

  hostUpdated(): void {
    this._initTabindex();
  }

  /** Returns the currently focused item index. */
  get currentIndex(): number {
    return this._currentIndex;
  }

  /** Programmatically set the active item by index. */
  setCurrentIndex(index: number): void {
    const items = this._getItems();
    if (index >= 0 && index < items.length) {
      this._currentIndex = index;
      this._updateTabindex(items);
    }
  }

  /** Returns the list of items managed by this controller. */
  getItems(): HTMLElement[] {
    return this._getItems();
  }

  private _getItems(): HTMLElement[] {
    return Array.from(this._host.querySelectorAll<HTMLElement>(this._options.selector)).filter(
      (el) => !el.hasAttribute('disabled') && el.getAttribute('aria-disabled') !== 'true',
    );
  }

  private _initTabindex(): void {
    const items = this._getItems();
    if (items.length === 0) return;
    if (this._currentIndex >= items.length) {
      this._currentIndex = 0;
    }
    this._updateTabindex(items);
  }

  private _updateTabindex(items: HTMLElement[]): void {
    for (let i = 0; i < items.length; i++) {
      items[i]!.setAttribute('tabindex', i === this._currentIndex ? '0' : '-1');
    }
  }

  private _onFocusIn = (event: Event): void => {
    const target = event.target as HTMLElement;
    const items = this._getItems();
    const index = items.indexOf(target);
    if (index !== -1) {
      this._currentIndex = index;
      this._updateTabindex(items);
    }
  };

  private _onKeyDown(event: Event): void {
    const e = event as KeyboardEvent;
    const { orientation, loop } = this._options;

    const isNext =
      (orientation !== 'horizontal' && e.key === 'ArrowDown') ||
      (orientation !== 'vertical' && e.key === 'ArrowRight');

    const isPrev =
      (orientation !== 'horizontal' && e.key === 'ArrowUp') ||
      (orientation !== 'vertical' && e.key === 'ArrowLeft');

    const isFirst = e.key === 'Home';
    const isLast = e.key === 'End';

    if (!isNext && !isPrev && !isFirst && !isLast) return;

    e.preventDefault();
    const items = this._getItems();
    if (items.length === 0) return;

    let nextIndex = this._currentIndex;

    if (isNext) {
      nextIndex = this._currentIndex + 1;
      if (nextIndex >= items.length) {
        nextIndex = loop ? 0 : items.length - 1;
      }
    } else if (isPrev) {
      nextIndex = this._currentIndex - 1;
      if (nextIndex < 0) {
        nextIndex = loop ? items.length - 1 : 0;
      }
    } else if (isFirst) {
      nextIndex = 0;
    } else if (isLast) {
      nextIndex = items.length - 1;
    }

    this._currentIndex = nextIndex;
    this._updateTabindex(items);
    items[nextIndex]?.focus();
  }
}

import type { ReactiveController, ReactiveControllerHost } from 'lit';

export interface GridNavigationOptions {
  /** CSS selector for rows. Default: '[role="row"]' */
  rowSelector?: string;
  /** CSS selector for cells within a row. Default: '[role="gridcell"], [role="columnheader"]' */
  cellSelector?: string;
  /** Wrap around at ends. Default: true */
  loop?: boolean;
}

/**
 * 2D arrow key navigation for `role="grid"` widgets.
 * Extends the RovingTabindexController concept into rows × columns.
 */
export class GridNavigationController implements ReactiveController {
  private _host: ReactiveControllerHost & HTMLElement;
  private _options: Required<GridNavigationOptions>;
  private _handleKeyDown = this._onKeyDown.bind(this);
  private _rowIndex = 0;
  private _colIndex = 0;

  constructor(host: ReactiveControllerHost & HTMLElement, options?: GridNavigationOptions) {
    this._host = host;
    this._options = {
      rowSelector: options?.rowSelector ?? '[role="row"]',
      cellSelector: options?.cellSelector ?? '[role="gridcell"], [role="columnheader"]',
      loop: options?.loop ?? true,
    };
    host.addController(this);
  }

  hostConnected(): void {
    this._host.addEventListener('keydown', this._handleKeyDown);
    this._host.addEventListener('focusin', this._onFocusIn.bind(this));
    requestAnimationFrame(() => this._initTabindex());
  }

  hostDisconnected(): void {
    this._host.removeEventListener('keydown', this._handleKeyDown);
  }

  hostUpdated(): void {
    this._initTabindex();
  }

  /** Current focused row index. */
  get rowIndex(): number {
    return this._rowIndex;
  }

  /** Current focused column index. */
  get colIndex(): number {
    return this._colIndex;
  }

  /** Programmatically set the active cell. */
  setCurrentCell(row: number, col: number): void {
    const rows = this._getRows();
    if (row >= 0 && row < rows.length) {
      const cells = this._getCells(rows[row]!);
      if (col >= 0 && col < cells.length) {
        this._rowIndex = row;
        this._colIndex = col;
        this._updateTabindex();
      }
    }
  }

  private _getRows(): HTMLElement[] {
    return Array.from(this._host.querySelectorAll<HTMLElement>(this._options.rowSelector));
  }

  private _getCells(row: HTMLElement): HTMLElement[] {
    return Array.from(row.querySelectorAll<HTMLElement>(this._options.cellSelector)).filter(
      (el) => !el.hasAttribute('disabled') && el.getAttribute('aria-disabled') !== 'true',
    );
  }

  private _initTabindex(): void {
    const rows = this._getRows();
    if (rows.length === 0) return;
    if (this._rowIndex >= rows.length) this._rowIndex = 0;
    const cells = this._getCells(rows[this._rowIndex]!);
    if (this._colIndex >= cells.length) this._colIndex = 0;
    this._updateTabindex();
  }

  private _updateTabindex(): void {
    const rows = this._getRows();
    for (let r = 0; r < rows.length; r++) {
      const cells = this._getCells(rows[r]!);
      for (let c = 0; c < cells.length; c++) {
        cells[c]!.setAttribute(
          'tabindex',
          r === this._rowIndex && c === this._colIndex ? '0' : '-1',
        );
      }
    }
  }

  private _onFocusIn = (event: Event): void => {
    const target = event.target as HTMLElement;
    const rows = this._getRows();
    for (let r = 0; r < rows.length; r++) {
      const cells = this._getCells(rows[r]!);
      const c = cells.indexOf(target);
      if (c !== -1) {
        this._rowIndex = r;
        this._colIndex = c;
        this._updateTabindex();
        return;
      }
    }
  };

  private _onKeyDown(event: Event): void {
    const e = event as KeyboardEvent;
    const rows = this._getRows();
    if (rows.length === 0) return;

    const { loop } = this._options;
    let newRow = this._rowIndex;
    let newCol = this._colIndex;
    let handled = false;

    const currentCells = this._getCells(rows[newRow]!);

    switch (e.key) {
      case 'ArrowRight':
        newCol++;
        if (newCol >= currentCells.length) {
          newCol = loop ? 0 : currentCells.length - 1;
        }
        handled = true;
        break;
      case 'ArrowLeft':
        newCol--;
        if (newCol < 0) {
          newCol = loop ? currentCells.length - 1 : 0;
        }
        handled = true;
        break;
      case 'ArrowDown':
        newRow++;
        if (newRow >= rows.length) {
          newRow = loop ? 0 : rows.length - 1;
        }
        handled = true;
        break;
      case 'ArrowUp':
        newRow--;
        if (newRow < 0) {
          newRow = loop ? rows.length - 1 : 0;
        }
        handled = true;
        break;
      case 'Home':
        if (e.ctrlKey) {
          newRow = 0;
          newCol = 0;
        } else {
          newCol = 0;
        }
        handled = true;
        break;
      case 'End':
        if (e.ctrlKey) {
          newRow = rows.length - 1;
          const lastRowCells = this._getCells(rows[newRow]!);
          newCol = lastRowCells.length - 1;
        } else {
          newCol = currentCells.length - 1;
        }
        handled = true;
        break;
    }

    if (!handled) return;

    e.preventDefault();

    // Clamp column to the new row's cell count
    const targetCells = this._getCells(rows[newRow]!);
    if (newCol >= targetCells.length) newCol = targetCells.length - 1;
    if (newCol < 0) newCol = 0;

    this._rowIndex = newRow;
    this._colIndex = newCol;
    this._updateTabindex();
    targetCells[newCol]?.focus();
  }
}

import type { ReactiveController, ReactiveControllerHost } from 'lit';
import {
  computePosition,
  autoUpdate,
  flip,
  shift,
  offset,
  arrow,
  size,
  type Placement,
  type VirtualElement,
} from '@floating-ui/dom';

export interface OverlayOptions {
  /** Preferred placement relative to reference. Default: 'bottom' */
  placement?: Placement;
  /** Offset in pixels from the reference. Default: 8 */
  offset?: number;
  /** Enable automatic flip when clipped. Default: true */
  flip?: boolean;
  /** Enable shift along the axis to stay in view. Default: true */
  shift?: boolean;
  /** CSS selector for the arrow element within the floating element. */
  arrowSelector?: string;
  /** Match the floating element width to the reference. Default: false */
  matchWidth?: boolean;
}

/**
 * Wraps Floating UI for viewport-aware positioning of overlay elements.
 * Used by Tooltip, Popover, Select, Menu, etc.
 */
export class OverlayController implements ReactiveController {
  private _host: ReactiveControllerHost & HTMLElement;
  private _options: Required<OverlayOptions>;
  private _cleanup: (() => void) | null = null;

  /** The resolved placement after flip/shift adjustments. */
  currentPlacement: Placement;

  constructor(host: ReactiveControllerHost & HTMLElement, options?: OverlayOptions) {
    this._host = host;
    this._options = {
      placement: options?.placement ?? 'bottom',
      offset: options?.offset ?? 8,
      flip: options?.flip ?? true,
      shift: options?.shift ?? true,
      arrowSelector: options?.arrowSelector ?? '',
      matchWidth: options?.matchWidth ?? false,
    };
    this.currentPlacement = this._options.placement;
    host.addController(this);
  }

  hostConnected(): void {}
  hostDisconnected(): void {
    this.hide();
  }

  /** Start auto-updating position of the floating element relative to the reference. */
  show(reference: HTMLElement | VirtualElement, floating: HTMLElement): void {
    this.hide();

    const middleware = [offset(this._options.offset)];

    if (this._options.flip) {
      middleware.push(flip({ padding: 8 }));
    }
    if (this._options.shift) {
      middleware.push(shift({ padding: 8 }));
    }
    if (this._options.matchWidth) {
      middleware.push(
        size({
          apply({ rects, elements }) {
            Object.assign(elements.floating.style, {
              width: `${rects.reference.width}px`,
            });
          },
        }),
      );
    }

    const arrowEl = this._options.arrowSelector
      ? floating.querySelector<HTMLElement>(this._options.arrowSelector)
      : null;
    if (arrowEl) {
      middleware.push(arrow({ element: arrowEl }));
    }

    this._cleanup = autoUpdate(reference as Element, floating, () => {
      computePosition(reference as Element, floating, {
        placement: this._options.placement,
        middleware,
      }).then(({ x, y, placement, middlewareData }) => {
        this.currentPlacement = placement;
        floating.setAttribute('data-placement', placement);

        Object.assign(floating.style, {
          left: `${x}px`,
          top: `${y}px`,
        });

        if (arrowEl && middlewareData.arrow) {
          const { x: ax, y: ay } = middlewareData.arrow;
          const side = placement.split('-')[0]!;
          const staticSide = { top: 'bottom', right: 'left', bottom: 'top', left: 'right' }[
            side
          ]!;

          Object.assign(arrowEl.style, {
            left: ax != null ? `${ax}px` : '',
            top: ay != null ? `${ay}px` : '',
            right: '',
            bottom: '',
            [staticSide]: '-4px',
          });
        }
      });
    });
  }

  /** Stop positioning and clean up. */
  hide(): void {
    if (this._cleanup) {
      this._cleanup();
      this._cleanup = null;
    }
  }

  /** Force an immediate reposition. */
  reposition(): void {
    // autoUpdate handles this, but you can trigger via show() again if needed
  }

  /** Update placement option. */
  setPlacement(placement: Placement): void {
    this._options.placement = placement;
  }

  /** Update offset option. */
  setOffset(value: number): void {
    this._options.offset = value;
  }
}

